import{RestClientBase}from"../Common/RestClientBase";export class FeatureAvailabilityRestClient extends RestClientBase{constructor(e){super(e)}async getAllFeatureFlags(e){const a={userEmail:e};return this.beginRequest({apiVersion:"7.2-preview.1",routeTemplate:"_apis/FeatureFlags/{name}",queryParams:a})}async getFeatureFlagByName(e,a){const t={checkFeatureExists:a};return this.beginRequest({apiVersion:"7.2-preview.1",routeTemplate:"_apis/FeatureFlags/{name}",routeValues:{name:e},queryParams:t})}async getFeatureFlagByNameAndUserEmail(e,a,t){const s={userEmail:a,checkFeatureExists:t};return this.beginRequest({apiVersion:"7.2-preview.1",routeTemplate:"_apis/FeatureFlags/{name}",routeValues:{name:e},queryParams:s})}async getFeatureFlagByNameAndUserId(e,a,t){const s={userId:a,checkFeatureExists:t};return this.beginRequest({apiVersion:"7.2-preview.1",routeTemplate:"_apis/FeatureFlags/{name}",routeValues:{name:e},queryParams:s})}async updateFeatureFlag(e,a,t,s,r){const u={userEmail:t,checkFeatureExists:s,setAtApplicationLevelAlso:r};return this.beginRequest({apiVersion:"7.2-preview.1",method:"PATCH",routeTemplate:"_apis/FeatureFlags/{name}",routeValues:{name:a},queryParams:u,body:e})}};